-- =========================================================================
-- 4. Productos
-- =========================================================================
--
-- El volcado no traía productos, así que el catálogo se escribe en
-- `generar.py` con precios de referencia del mercado peruano.
--
-- La imagen es el logotipo de la marca. No es una foto del producto y no
-- pretende serlo: es lo que hay, es real, y una rejilla de logotipos de
-- marcas que existen se lee mucho mejor que una de imágenes de relleno
-- sacadas de un servicio aleatorio.

