',
     'Cables usb', 'Nexxt', 24.9, NULL, 300, false),
    ('FER-CABLES-112', 'Cable HDMI 2.0 de 3 m', 'cable-hdmi-2-0-de-3-m', '4K a 60 Hz. Conectores chapados en oro.', '4K a 60 Hz. Conectores chapados en oro.

