- Garantía del fabricante contra defectos de fábrica.
- Factura o boleta electrónica al momento de la compra.
',
     'Cables usb', 'Nexxt', 46.0, NULL, 180, false),
    ('FER-CABLES-113', 'Extensión USB 3.0 de 5 m Activa', 'extension-usb-3-0-de-5-m-activa', 'Con amplificador de señal para cámaras e impresoras.', 'Con amplificador de señal para cámaras e impresoras.

