) AS v(sku, nombre, slug, descripcion_corta, descripcion, subcategoria, marca,
       precio, precio_anterior, stock, destacado)
JOIN subcategoria s ON s.nombre = v.subcategoria
LEFT JOIN marca m ON m.nombre = v.marca;

-- La imagen del producto es la de su marca.
INSERT INTO producto_imagen (fk_id_producto, fk_id_archivo, orden)
SELECT p.id_producto, m.fk_id_archivo, 0
FROM producto p
JOIN marca m ON m.id_marca = p.fk_id_marca
WHERE m.fk_id_archivo IS NOT NULL;

-- Y si la marca no tiene logotipo, la de su subcategoría: publicar exige
-- al menos una imagen (RN-009), así que ninguno puede quedarse sin ella.
INSERT INTO producto_imagen (fk_id_producto, fk_id_archivo, orden)
SELECT p.id_producto, s.fk_id_archivo, 0
FROM producto p
JOIN subcategoria s ON s.id_subcategoria = p.fk_id_subcategoria
WHERE s.fk_id_archivo IS NOT NULL
  AND NOT EXISTS (SELECT 1 FROM producto_imagen pi WHERE pi.fk_id_producto = p.id_producto);

-- Lo que aun así se quedó sin imagen no puede estar publicado.
UPDATE producto SET activo = false
WHERE NOT EXISTS (SELECT 1 FROM producto_imagen pi WHERE pi.fk_id_producto = producto.id_producto);


